"""Prepare a reviewable public-source ZIP without making commits or pushing.

The immutable base must be a previously reviewed public commit. Only explicit
source overlays are accepted; release binaries and language data are separate.
After review, commit the ZIP's exact bytes, not a fresh read of the worktree.
"""
import argparse
import hashlib
import io
import json
import os
from pathlib import Path, PurePosixPath
import re
import subprocess
import tarfile
import uuid
import zipfile

ROOT = Path(__file__).resolve().parents[2]
PUBLIC_BASE = '7da9b9469ac42d719e416bd7b1764a03ba8446bd'
LAUNCHER = ('Launcher.cs', 'SelfUpdate.cs', 'UiText.cs', 'LocalBuild.cs', 'GameLanguage.cs', 'GameOptions.cs',
            'InstallProgress.cs', 'PrebuiltInstall.cs', 'build_launcher.ps1', 'README.txt')
LOCAL_BUILD = ('apply_hooks.py', 'build.ps1', 'finalize.py', 'install.ps1', 'prepare.py',
               'setup_tools.ps1', 'compile_cache.py', 'incremental.py', 'install_prebuilt.ps1',
               'language_views.py', 'prebuilt_finalize.py')
NATIVE = ('CMakeLists.txt', 'shader_prep_main.c', 'shader_prep_selftest.c', 'battle_voice_catalog.cpp', 'battle_voice_catalog.h', 'battle_voice_subtitles.cpp')
SDK = ('libs/video/rsx_live_draw.c', 'libs/video/rsx_shader_prep.h', 'libs/video/rsx_shader_prep_runtime.h', 'libs/video/rsx_null_backend.c', 'libs/video/macross_ui_language.h', 'libs/video/macross_ui_strings.def', 'libs/video/rsx_fp_decompiler.c',
       'libs/system/savedlg_win32.h', 'libs/system/savedlg_language.h', 'libs/system/savedlg_strings.def',
       'runtime/ppu/ppu_fs.cpp', 'runtime/syscalls/sys_fs.c')
OVERLAYS = tuple('tools/launcher/' + p for p in LAUNCHER) + tuple('tools/local_build/' + p for p in LOCAL_BUILD)
OVERLAYS += ('tools/dist/prebuilt_package.py', 'tools/dist/split_language_packages.py', 'tools/dist/english_data_package.py', 'tools/dist/audit_prebuilt_release.py', 'tools/dist/public_source_snapshot.py', 'tools/dist/README-public-source.md', 'docs/release-0.3.0.md', 'tools/dist/make_dist.py', 'tools/dist/check_dist_env.py', 'tools/dist/release_profile.py', 'tools/dist/release_inputs.py', 'tools/play/native_binary_launch.py') + tuple('native/macross30/' + p for p in NATIVE)
OVERLAYS += tuple('vendor/ps3recomp-master/' + p for p in SDK)
# Shader seed/PSO inventory tooling imported by prebuilt_package.py and audit_prebuilt_release.py.
OVERLAYS += tuple('tools/shader_cache/' + p for p in ('d3dc.py', 'shader_seed.py', 'stage_program_assets.py', 'patch_live_draw.py'))
FORBIDDEN = {'.exe', '.dll', '.elf', '.self', '.bin', '.iso', '.prx', '.sprx', '.obj', '.o', '.a', '.lib', '.pdb', '.zip', '.7z', '.pyc'}
GENERATED_PREFIXES = ('native/macross30/recompiled/', 'native/macross30/raw_jobs/',
                      'native/macross30/spu_gameplay/', 'native/macross30/spu_graphics/',
                      'native/macross30/spu_posttask_native/', 'native/macross30/spu/')
INDEPENDENT_STUB = 'vendor/ps3recomp-master/runtime/spu/spu_tsp_weak.c'
INDEPENDENT_STUB_SHA = '65143ebc6a9fb0cfa7ced7118218477343a07e697b06ceefab1be0d946ff3579'


def sha(data):
    return hashlib.sha256(data).hexdigest()


def valid_path(name):
    path = PurePosixPath(name)
    if path.is_absolute() or '..' in path.parts or '\\' in name or ':' in name or not name:
        raise ValueError('Unsafe snapshot path: ' + name)
    if path.suffix.lower() in FORBIDDEN or name.startswith(GENERATED_PREFIXES) or name.endswith('/geom_c5b0_capture_contract.h'):
        raise ValueError('Binary/generated file prohibited in source snapshot: ' + name)
    if path.name.startswith('spu_recomp'):
        raise ValueError('Generated source filename prohibited: ' + name)


def audit(files, original=None):
    folded = set()
    for name, data in files.items():
        valid_path(name)
        if name.lower() in folded:
            raise ValueError('Case-insensitive duplicate: ' + name)
        folded.add(name.lower())
        if data.startswith((b'MZ', b'\x7fELF', b'SCE\0', b'!<arch>')):
            raise ValueError('Binary magic in source snapshot: ' + name)
        text = data.decode('utf8')
        stub = name == INDEPENDENT_STUB and sha(data.replace(b'\r\n', b'\n')) == INDEPENDENT_STUB_SHA
        if not stub and Path(name).suffix in ('.c', '.cpp', '.h', '.inc') and re.search(
                r'Auto-generated by (?:spu|ppu)_lifter|Generated exactoriginalcode|void (?:func_[0-9A-F]{8}|\w+_spu_func_[0-9A-F]{8})\([^;]*\)\s*\{', text):
            raise ValueError('Generated game code in snapshot: ' + name)
        if original is not None:
            for match in re.finditer(r'(?<![\w])(?:0x[\da-fA-F]+|\d+)[uUlL]*(?:\s*,\s*(?:0x[\da-fA-F]+|\d+)[uUlL]*){63,}', text):
                values = [int(token.rstrip('uUlL'), 16 if token.lower().startswith('0x') else 10)
                          for token in re.split(r'\s*,\s*', match[0])]
                if max(values) <= 255 and bytes(values) in original:
                    raise ValueError('Original byte array in source snapshot: ' + name)


def prepare(output, readme, original=None, base=PUBLIC_BASE):
    if base != PUBLIC_BASE:
        raise ValueError('Only the reviewed public baseline is accepted')
    archive = subprocess.check_output(['git', 'archive', base], cwd=ROOT)
    files = {}
    with tarfile.open(fileobj=io.BytesIO(archive)) as source:
        for entry in source:
            if entry.isdir():
                continue
            if not entry.isfile():
                raise ValueError('Link or special entry in base snapshot: ' + entry.name)
            files[entry.name] = source.extractfile(entry).read()
    changes = []
    for name in OVERLAYS:
        path = ROOT / name
        before = path.stat()
        data = path.read_bytes()
        after = path.stat()
        if before.st_size != after.st_size or before.st_mtime_ns != after.st_mtime_ns:
            raise ValueError('Overlay changed while reading; retry after freezing source: ' + name)
        changes.append(dict(path=name, old_sha256=sha(files[name]) if name in files else None,
                            sha256=sha(data), bytes=len(data), origin='explicit worktree overlay'))
        files[name] = data
    files['README.md'] = Path(readme).read_bytes()
    changes.append(dict(path='README.md', sha256=sha(files['README.md']), bytes=len(files['README.md']), origin='reviewed release README'))
    audit(files, original)
    output = Path(output)
    output.mkdir(parents=True, exist_ok=True)
    zip_path = output / 'public-source-reviewed.zip'
    with zipfile.ZipFile(zip_path, 'w', compression=zipfile.ZIP_DEFLATED) as archive:
        for name, data in sorted(files.items()):
            archive.writestr(name, data)
    report = dict(passed=True, public_base=base, file_count=len(files), overlay_count=len(changes),
                  source_zip=dict(file=zip_path.name, bytes=zip_path.stat().st_size, sha256=sha(zip_path.read_bytes())),
                  original_byte_array_scan=original is not None, changes=changes,
                  files=[dict(path=name, bytes=len(data), sha256=sha(data)) for name, data in sorted(files.items())],
                  excluded='Private history, unrelated localization tools/data, generated PPU/SPU sources, full EBOOT and all binaries',
                  next_step='Review this ZIP/report, then stage these exact bytes in a temporary Git index with parent public_base. No commit or push was performed.')
    (output / 'public-source-review.json').write_text(json.dumps(report, indent=2) + '\n', encoding='utf8')
    return report


def commit_reviewed(output, message='Release reviewed prebuilt runtime and local-EBOOT installation source'):
    """Make a local clean-parent commit from the reviewed ZIP, never from HEAD."""
    output = Path(output).resolve()
    report = json.loads((output / 'public-source-review.json').read_text(encoding='utf8'))
    if not report.get('passed') or not report.get('original_byte_array_scan') or report.get('public_base') != PUBLIC_BASE:
        raise ValueError('A passing full review is required before committing')
    archive_bytes = (output / 'public-source-reviewed.zip').read_bytes()
    if sha(archive_bytes) != report['source_zip']['sha256']:
        raise ValueError('Reviewed ZIP changed')
    expected = {row['path']: row['sha256'] for row in report['files']}
    with zipfile.ZipFile(io.BytesIO(archive_bytes)) as archive:
        if len(archive.namelist()) != len(expected) or set(archive.namelist()) != set(expected):
            raise ValueError('Reviewed ZIP inventory changed')
        files = {name: archive.read(name) for name in archive.namelist()}
    if any(sha(data) != expected[name] for name, data in files.items()):
        raise ValueError('Reviewed source file changed')
    audit(files)
    index = output / ('source-index-' + uuid.uuid4().hex)
    env = dict(os.environ, GIT_INDEX_FILE=str(index), GIT_AUTHOR_NAME='Macross30 Release',
               GIT_AUTHOR_EMAIL='release@macross30.invalid', GIT_COMMITTER_NAME='Macross30 Release',
               GIT_COMMITTER_EMAIL='release@macross30.invalid')
    def git(*args, data=None):
        return subprocess.check_output(['git', *args], cwd=ROOT, env=env, input=data).decode().strip()
    try:
        git('read-tree', '--empty')
        rows = []
        for name, data in sorted(files.items()):
            rows.append('100644 ' + git('hash-object', '-w', '--stdin', data=data) + '\t' + name + '\n')
        git('update-index', '--index-info', data=''.join(rows).encode())
        tree = git('write-tree')
        commit = git('commit-tree', tree, '-p', PUBLIC_BASE, '-m', message)
        (output / 'public-source-commit.txt').write_text(commit + '\n', encoding='ascii')
        return commit
    finally:
        if index.exists():
            index.unlink()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output', required=True, type=Path)
    parser.add_argument('--readme', required=True, type=Path)
    parser.add_argument('--original-elf', type=Path)
    args = parser.parse_args()
    result = prepare(args.output, args.readme, args.original_elf.read_bytes() if args.original_elf else None)
    print(json.dumps({k: result[k] for k in ('passed', 'file_count', 'overlay_count', 'source_zip')}, indent=2))


if __name__ == '__main__':
    main()
